import axios from 'axios';
import { axiosInstance } from './globalInstance';

const { CancelToken } = axios;
let cancel = null;
let request = 0;

class SubscriptionApi {
  static async getClientSubscriptionToken(orgId) {
    return await axiosInstance.get(
      `${process.env.API_URL}/organization/${orgId}/subscription/client-token`,
      {
        withCredentials: true,
        validateStatus(status) {
          return status >= 200 && status < 401; // default
        },
      }
    );
  }

  static async getCurrentSubscription(orgId, chargebeeData) {
    request++;
    if (cancel) {
      await cancel(request);
    }
    const apiUrl = `${process.env.SUBSCRIPTION_URL}/subscription/organization/${orgId}/current-subscription${chargebeeData ? '?chargebee_data=true' : ''}`

    return await axiosInstance.get(
      apiUrl,
      {
        withCredentials: true,
        validateStatus(status) {
          return status >= 200 && status < 401; // default
        },
        cancelToken: new CancelToken((c) => {
          // An executor function receives a cancel function as a parameter
          cancel = c;
          request = 0;
        }),
      }
    );
  }

  // Self-serve cancellation endpoint (das-api: SelfServeSubscriptionCancellationView,
  // route name "self-serve-cancel-subscription"). Schedules cancellation at term end;
  // backend enforces self-serve + non-guest/admin + org-owner.
  static async cancelSelfServeSubscription(orgId) {
    return await axiosInstance.post(
      `${process.env.SUBSCRIPTION_URL}/subscription/organization/${orgId}/cancel-subscription`,
      {},
      { withCredentials: true }
    );
  }

  static async getActiveSubscription(orgId) {
    // request++
    // if (cancel) {
    //   await cancel(request)
    // }
    const apiUrl = `${process.env.SUBSCRIPTION_URL}/subscription/organization/${orgId}/active-subscription`
    const response = await axiosInstance.get(
      apiUrl,
      {
        withCredentials: true,
        validateStatus(status) {
          return status >= 200 && status < 401; // default
        },
        // cancelToken: new CancelToken(function executor (c) {
        //   // An executor function receives a cancel function as a parameter
        // cancel = c
        // request = 0
        // })
      }
    );
    // cancel = null
    return response;
  }

  static async getOrgAvailablePlans(orgId) {
    return await axiosInstance.get(
      `${process.env.API_URL}/organization/${orgId}/subscription/available-plans`,
      {
        withCredentials: true,
        validateStatus(status) {
          return status >= 200 && status < 401; // default
        },
      }
    );
  }

  static async getPaymentHistory(orgId, pageNumber, csrf) {
    const paymentHistory = await axiosInstance({
      method: 'GET',
      url: `${process.env.SUBSCRIPTION_URL}/subscription/organization/${orgId}/invoices?page=${pageNumber}`,
      withCredentials: true,
    });
    return paymentHistory;
  }

  static async getQueryPlanChange(orgId, planType, csrf) {
    return await axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/organization/${orgId}/subscription/query-plan-change`,
      data: { planType, _csrf: csrf },
      withCredentials: true,
    });
  }

  static async updatePlan(orgId, planCode, nonce, csrf, appList, teamList) {
    const updatedPlan = await axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/organization/${orgId}/subscription/update-your-plan`,
      data: {
        uxcamPlan: planCode,
        paymentMethodNonce: nonce,
        _csrf: csrf,
        apps: appList,
        team: teamList,
      },
      withCredentials: true,
    });
    return updatedPlan;
  }

  static async changePayment(orgId, nonce, csrf) {
    const updatedPlan = await axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/organization/${orgId}/subscription/change-payment-method`,
      data: { paymentMethodNonce: nonce, _csrf: csrf },
      withCredentials: true,
    });
    return updatedPlan;
  }

  static async getOrgAppTeam(orgId) {
    return await axiosInstance.get(
      `${process.env.API_URL}/organization/${orgId}/subscription/list-app-team`,
      {
        withCredentials: true,
        validateStatus(status) {
          return status >= 200 && status < 401; // default
        },
      }
    );
  }

  static async getInvoice(orgId, id, csrf) {
    const paymentHistory = await axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/organization/${orgId}/subscription/receipt`,
      data: { id, _csrf: csrf },
      withCredentials: true,
    });
    return paymentHistory;
  }

  static async getOverageInvoice(orgId, id) {
    const paymentHistory = await axiosInstance({
      method: 'GEt',
      url: `${process.env.API_URL}/overage/${orgId}/transaction/${id}/receipt`,
      withCredentials: true,
    });
    return paymentHistory;
  }

  static async getDownloadableInvoice(orgId, invoiceId) {
   // `${process.env.SUBSCRIPTION_URL}/subscription/chargebee/transaction/${id}/get-invoice-pdfs`
   // `${process.env.API_URL}/transaction/${id}/invoice-pdf`,
    const paymentHistory = await axiosInstance({
      method: 'GET',
      url: `${process.env.SUBSCRIPTION_URL}/subscription/organization/${orgId}/invoice/${invoiceId}/detail`,
      withCredentials: true,
    });
    return paymentHistory;
  }

  static async updateInvoiceRecipientsAndAddress(orgId, data) {
    return axiosInstance({
      method: 'PUT',
      url: `${process.env.API_URL}/organization/${orgId}/update-subscription`,
      data,
      withCredentials: true,
    });
  }

  static async postRequestQuote(orgId, data) {
    return await axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/organization/${orgId}/subscription/request-quote`,
      data,
      withCredentials: true,
    });
  }

  static async getQueryPremiumPlan(orgId, planCode, csrf) {
    const updatedPlan = await axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/organization/${orgId}/subscription/query-premium-plan-change`,
      data: { uxcamPlan: planCode, _csrf: csrf },
      withCredentials: true,
    });
    return updatedPlan;
  }

  static async retryPayment(orgId) {
    return await axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/organization/${orgId}/subscription/retry-payment`,
      withCredentials: true,
    });
  }

  static async toggleSessionRecording(orgId, payload) {
    const res = await axiosInstance({
      method: 'PUT',
      url: `${process.env.SUBSCRIPTION_URL}/organization/${orgId}/toggle-overage-recording`,
      withCredentials: true,
      data: payload
    });
    return res;
  }

  static async getSessionUsage(orgId) {
    return await axiosInstance.get(
      `${process.env.API_URL}/organization/${orgId}/team/session-usage-percentage`,
      {
        withCredentials: true,
        validateStatus(status) {
          return status >= 200 && status < 401; // default
        },
      }
    );
  }

  static async updateSessionUsage(orgId, data) {
    return axiosInstance({
      method: 'PUT',
      url: `${process.env.API_URL}/organization/${orgId}/team/session-usage-percentage`,
      data,
      withCredentials: true,
    });
  }

  static async getBillingInfo(orgId) {
    return axiosInstance({
      method: 'GET',
      url: `${process.env.SUBSCRIPTION_URL}/subscription/organization/${orgId}/billing-info/`,
      withCredentials: true,
    })
      .then( ( res ) => res.data?.data );
  }

  static async setRecipientEmails(orgId, data) {
    return axiosInstance({
      method: 'PUT',
      url: `${process.env.SUBSCRIPTION_URL}/subscription/organization/${orgId}/billing-info/recipients/`,
      data: {
        emails: data,
      },
      withCredentials: true,
    })
  }

  static async setBillingAddress(orgId, data) {
    return axiosInstance({
      method: 'PUT',
      url: `${process.env.SUBSCRIPTION_URL}/subscription/organization/${orgId}/billing-info/address/`,
      data,
      withCredentials: true,
    })
  }

  static getWebSessionUsage(orgId) {
    return axiosInstance.get(
      `${process.env.API_URL}/organization/${orgId}/team/web-session-usage-percentage`,
      {
        withCredentials: true,
        validateStatus(status) {
          return status >= 200 && status < 401; // default
        },
      }
    );
  }

  static async updateWebSessionUsage(orgId, data) {
    return axiosInstance({
      method: 'PUT',
      url: `${process.env.API_URL}/organization/${orgId}/team/web-session-usage-percentage`,
      data,
      withCredentials: true,
    });
  }

  static async getUnpaidInvoicePaymentLink(orgId) {
    return axiosInstance({
      method: 'GET',
      url: `${process.env.SUBSCRIPTION_URL}/subscription/organization/${orgId}/unpaid-invoice-payment-link`,
      withCredentials: true,
    });
  }

  static async getAIOverview(orgId) {
    return axiosInstance({
      method: 'GET',
      url: `${process.env.SUBSCRIPTION_URL}/app/organization/${orgId}/ai-overview/`,
      withCredentials: true,
    });
  }

  static async toggleAIForApp(orgId, appId, isAIEnabled) {
    return axiosInstance({
      method: 'POST',
      url: `${process.env.SUBSCRIPTION_URL}/app/organization/${orgId}/${appId}/toggle-ai/`,
      data: { isAIEnabled },
      withCredentials: true,
    });
  }

  static async getAIUsageOverview(orgId) {
    return axiosInstance({
      method: 'GET',
      url: `${process.env.SUBSCRIPTION_URL}/subscription/organization/${orgId}/ai-overview`,
      withCredentials: true,
    });
  }

}

export default SubscriptionApi;
