import { axiosInstance } from 'services/globalInstance';

const AUTH_BASE_URL = process.env.AUTH_API_URL;
const DASHBOARD_BASE_URL = process.env.API_URL;
const SUBSCRIPTION_BASE_URL = process.env.SUBSCRIPTION_URL;

class SettingApi {
  static async getTeamList(orgId) {
    return axiosInstance({
      method: 'GET',
      url: `${AUTH_BASE_URL}/org/${orgId}/team`,
      withCredentials: true,
    });
  }

  static async inviteTeamMates(payload) {
    const { data, orgId } = payload;
    return axiosInstance({
      method: 'POST',
      url: `${AUTH_BASE_URL}/org/${orgId}/team/invite`,
      data,
      withCredentials: true,
    });
  }

  static async editTeamMates(payload) {
    const { orgId, data, id, inviteId } = payload;
    return axiosInstance({
      method: 'PUT',
      url: `${AUTH_BASE_URL}/org/${orgId}/team/${ inviteId ? `invite/${inviteId}` : id}`,
      data,
      withCredentials: true,
    });
  }

  static async resendInvite(value, orgId) {
    return axiosInstance({
      method: 'POST',
      url: `${AUTH_BASE_URL}/org/${orgId}/team/invite/resend`,
      data: { email: value },
      withCredentials: true,
    });
  }

  static async deleteTeammates(payload) {
    const { orgId, data } = payload;
    return axiosInstance({
      method: 'POST',
      url: `${AUTH_BASE_URL}/org/${orgId}/team/delete`,
      data,
      withCredentials: true,
    });
  }

  static async transferOwnership(customerId, orgId) {
    return axiosInstance({
      method: 'PUT',
      url: `${AUTH_BASE_URL}/org/${orgId}/transfer-ownership`,
      data: { id: customerId },
      withCredentials: true,
    });
  }

  static async getQueryPlanChange(orgId, uxcamPlan) {
    return axiosInstance({
      method: 'POST',
      url: `${DASHBOARD_BASE_URL}/organization/${orgId}/subscription/query-premium-plan-change`,
      data: { uxcamPlan },
      withCredentials: true,
    });
  }

  static async changePayment(orgId, nonce) {
    return axiosInstance({
      method: 'POST',
      url: `${DASHBOARD_BASE_URL}/organization/${orgId}/subscription/change-payment-method`,
      data: { paymentMethodNonce: nonce },
      withCredentials: true,
    });
  }

  static async updatePlan(orgId, planCode, nonce, appList, teamList) {
    return axiosInstance({
      method: 'POST',
      url: `${DASHBOARD_BASE_URL}/organization/${orgId}/subscription/update-your-plan`,
      data: {
        uxcamPlan: planCode,
        paymentMethodNonce: nonce,
        apps: appList,
        team: teamList,
      },
      withCredentials: true,
    });
  }

  static async getClientSubscriptionToken(orgId) {
    return axiosInstance({
      method: 'GET',
      url: `${DASHBOARD_BASE_URL}/organization/${orgId}/subscription/client-token`,
      withCredentials: true,
    });
  }

  static async getOrgAppList(orgId) {
    return axiosInstance({
      method: 'GET',
      url: `${DASHBOARD_BASE_URL}/organization/${orgId}/app/list`,
      withCredentials: true,
    });
  }

  static async createApp(data, orgId) {
    return axiosInstance({
      method: 'POST',
      url: `${SUBSCRIPTION_BASE_URL}/app/create-with-region/organization/${orgId}`,
      data,
      withCredentials: true,
    });
  }

  static async updateApp(value, applicationId) {
    return axiosInstance({
      method: 'PUT',
      url: `${DASHBOARD_BASE_URL}/app/${applicationId}/update-name`,
      data: { name: value },
      withCredentials: true,
    });
  }

  static async deleteApp(data, applicationId) {
    return axiosInstance({
      method: 'DELETE',
      url: `${DASHBOARD_BASE_URL}/app/${applicationId}`,
      withCredentials: true,
      data,
    });
  }

  static async updateAppImage(data, appId) {
    return axiosInstance({
      method: 'POST',
      url: `${SUBSCRIPTION_BASE_URL}/app/${appId}/update-app-image`,
      data,
      withCredentials: true,
    });
  }

  static async getRolesAndPermission() {
    return axiosInstance({
      method: 'GET',
      url: `${AUTH_BASE_URL}/user/roles`,
      withCredentials: true,
    });
  }

  static async getNewProfile() {
    return axiosInstance({
      method: 'GET',
      url: `${AUTH_BASE_URL}/user/profile`,
      withCredentials: true,
    });
  }

  static async getAllAppList(orgId) {
    return axiosInstance({
      method: 'GET',
      url: `${DASHBOARD_BASE_URL}/organization/${orgId}/app`,
      withCredentials: true,
    });
  }

  static async updateUserName(data) {
    return axiosInstance({
      method: 'POST',
      url: `${AUTH_BASE_URL}/user/profile/update-name`,
      data,
      withCredentials: true,
    });
  }

  static async fetchMFAStatus() {
    return axiosInstance({
      method: 'GET',
      url: `${DASHBOARD_BASE_URL}/profile/enable-mfa`,
      withCredentials: true,
    });
  }

  static async updateMFAStatus(data, endPoint) {
    return axiosInstance({
      method: 'POST',
      url: `${DASHBOARD_BASE_URL}/profile/${endPoint}`,
      data,
      withCredentials: true,
    });
  }

  static async getChargebeeLink(url) {
    return axiosInstance({
      method: 'GET',
      url: `${process.env.SUBSCRIPTION_URL}/${url}`,
      withCredentials: true,
    });
  }

  static async updateOrgName(data, OrgId) {
    return axiosInstance({
      method: 'PUT',
      url: `${DASHBOARD_BASE_URL}/organization/${OrgId}/update-name`,
      data,
      withCredentials: true,
    });
  }

  static async updateOrgImage(data, orgId) {
    return axiosInstance({
      method: 'POST',
      url: `${SUBSCRIPTION_BASE_URL}/organization/${orgId}/update-org-image`,
      data,
      withCredentials: true,
    });
  }

  static async emailToTeammates(payload) {
    const { orgId, data } = payload;
    return axiosInstance({
      method: 'POST',
      url: `${AUTH_BASE_URL}/org/${orgId}/team/developer-invite`,
      data,
      withCredentials: true,
    });
  }

  static async fetchAppSetting(appId) {
    return axiosInstance({
      method: 'GET',
      url: `${SUBSCRIPTION_BASE_URL}/app/${appId}/recording-setting`,
      withCredentials: true,
    });
  }

  static async updateDataCaptureAndRecording(appId, data) {
    return axiosInstance({
      method: 'PUT',
      url: `${SUBSCRIPTION_BASE_URL}/app/${appId}/recording-setting`,
      data,
      withCredentials: true,
    });
  }

  static async updateProfileInfo(data) {
    return axiosInstance({
      method: 'PUT',
      url: `${AUTH_BASE_URL}/user/update-profile`,
      data,
      withCredentials: true,
    });
  }
  
  static async updateProfileRemindMeLater() {
    return axiosInstance({
      method: 'POST',
      url: `${AUTH_BASE_URL}/user/update-profile/remind-me-later`,
      data: {},
      withCredentials: true,
    });
  }
  
  static async updatePaymentInfo(payload) {
    const { requestUrl, data } = payload;
    return axiosInstance({
      method: 'POST',
      url: `${DASHBOARD_BASE_URL}/${requestUrl}`,
      data,
      withCredentials: true,
    });
  }

  static async fetchCardPaymentInfo(orgId) {
    return axiosInstance({
      method: 'GET',
      url: `${SUBSCRIPTION_BASE_URL}/subscription/payment/organization/${orgId}`,
      withCredentials: true,
    });
  }

  static async updateChargebeeLink(url, payload) {
    return axiosInstance({
      method: 'POST',
      url: `${SUBSCRIPTION_BASE_URL}/${url}`, 
      data: payload,
      withCredentials: true,
    });
  }

  static async duplicateDomainAccess(token) {
    const response = await axiosInstance.post(`${AUTH_BASE_URL}/org/request-access/${token}`, {});
    return response
  }

  static async downgradeToFreePlan(orgId){
    return axiosInstance({
      method: 'POST',
      url: `${SUBSCRIPTION_BASE_URL}/subscription/switch-to-free-plan/organization/${orgId}`,
      withCredentials: true,
    })
  }

}


export default SettingApi;
